/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/marketing/brand-mark.tsx; derived here under Apache-2.0.
 */
export function BrandMark({ className }: { className?: string }) {
	return (
		<svg
			viewBox="0 0 96 48"
			className={className}
			xmlns="http://www.w3.org/2000/svg"
			aria-hidden="true"
		>
			<circle
				cx="24"
				cy="24"
				r="24"
				className="fill-[#1e1e1e] dark:fill-[#EEE]"
			/>
			<circle cx="48" cy="24" r="24" fill="#0090FD" />
			<circle cx="72" cy="24" r="24" fill="#FF5513" />
		</svg>
	);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/marketing/logo.tsx; derived here under Apache-2.0.
 */
import { cn } from "../lib/utils";

import { BrandMark } from "./brand-mark";

/**
 * Foglamp logo lockup — the three-circle brand mark next to the "Foglamp"
 * wordmark, set in Host Grotesk (the marketing display face, `font-display`).
 * Used in the marketing navbar and footer.
 */
export function Logo({ className }: { className?: string }) {
	return (
		<span className={cn("flex items-center gap-2", className)}>
			<BrandMark className="h-3.5 w-auto" />
			<span className="font-display text-lg font-semibold tracking-tight select-none">
				Foglamp
			</span>
		</span>
	);
}

